import pandas as pd
import ast
import json
import math
from datetime import datetime, timedelta

def standard_round(n):
    if n >= 0:
        return math.floor(n + 0.5)
    else:
        return math.ceil(n - 0.5)

def lev(s1, s2):
    if len(s1) < len(s2): return lev(s2, s1)
    if len(s2) == 0: return len(s1)
    prev = range(len(s2) + 1)
    for i, c1 in enumerate(s1):
        curr = [i + 1]
        for j, c2 in enumerate(s2):
            curr.append(min(prev[j + 1] + 1, curr[j] + 1, prev[j] + (c1 != c2)))
        prev = curr
    return prev[-1]

def get_billing_period(d, target_weekday):
    y, m = d.year, d.month
    d_first = datetime(y, m, 1)
    offset = (target_weekday - d_first.weekday() + 7) % 7
    start_of_current_month_period = d_first + timedelta(days=offset)

    if d >= start_of_current_month_period:
        return (y, m)
    else:
        if m == 1:
            return (y - 1, 12)
        else:
            return (y, m - 1)

def answer() -> dict[str, list[int]]:
    emp = pd.read_csv('/app/dataset/employees.csv', dtype={'PESEL': str})
    valid_pesels = set(emp['PESEL'])
    rates = emp.set_index('PESEL')['hourly_rate'].to_dict()

    tasks_df = pd.read_csv('/app/dataset/tasks.csv')
    task_pays = tasks_df.set_index('task_id')['pay_per_completion'].to_dict()
    valid_tasks = set(task_pays.keys())

    ts = pd.read_csv('/app/dataset/timesheet.csv', dtype={'employee_id': str})

    # Find earliest valid date to determine target weekday
    valid_dates = pd.to_datetime(ts['date'], errors='coerce').dropna()
    if valid_dates.empty:
        return {}
    earliest_date = valid_dates.min()
    target_weekday = earliest_date.weekday()

    pesel_map = {}
    for pid in ts['employee_id'].dropna().unique():
        if pid in valid_pesels:
            pesel_map[pid] = pid
        else:
            dists = [(v, lev(pid, v)) for v in valid_pesels]
            dists.sort(key=lambda x: x[1])
            pesel_map[pid] = dists[0][0]

    # Process all rows
    # Store salaries as results[pid][period] = total
    results = {p: {} for p in valid_pesels}
    all_periods = set()

    for idx, row in ts.iterrows():
        try:
            d = datetime.strptime(str(row['date']).strip(), '%Y-%m-%d')
        except:
            continue # Exclude invalid dates

        period = get_billing_period(d, target_weekday)
        all_periods.add(period)

        pid = pesel_map[row['employee_id']]

        t_str = str(row['performed_tasks']).strip()
        if t_str == 'nan':
            t_str = '[]'
        if not t_str.startswith('['): t_str = '[' + t_str
        if not t_str.endswith(']'): t_str = t_str + ']'
        try:
            t_list = ast.literal_eval(t_str)
        except:
            continue # Exclude malformed tasks

        # If any invalid tasks, exclude row entirely
        if any(t not in valid_tasks for t in t_list):
            continue

        bonus = sum(task_pays[t] for t in t_list)
        base = float(row['hours_worked']) * float(rates[pid])

        if period not in results[pid]:
            results[pid][period] = 0.0
        results[pid][period] += base + bonus

    sorted_periods = sorted(list(all_periods))

    final = {}
    for p in valid_pesels:
        final[p] = []
        for period in sorted_periods:
            amount = results[p].get(period, 0.0)
            final[p].append(standard_round(amount))

    return final

if __name__ == "__main__":
    with open("/app/answer.json", "w") as f:
        json.dump(answer(), f, default=list)
